import{_ as t,o,c as r,ae as i}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse('{"title":"React project files and directories names convention","description":"","frontmatter":{"id":"5541831634","title":"React project files and directories names convention","state":"Approved","created":"2020-12-01T00:00:00.000Z","tags":["react"],"category":"JavaScript"},"headers":[],"relativePath":"adrs/5541831634/README.md","filePath":"adrs/5541831634/README.md"}'),a={name:"adrs/5541831634/README.md"};function n(s,e,l,c,d,u){return o(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="react-project-files-and-directories-names-convention" tabindex="-1">React project files and directories names convention <a class="header-anchor" href="#react-project-files-and-directories-names-convention" aria-label="Permalink to &quot;React project files and directories names convention&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Across the ecosystem, we can find all sorts of files and directory naming conventions in React projects. The variety of conventions causes misalignment and shifts focus away from more important matters.</p><p>Although there are no silver bullets for this topic, committing to a convention will reduce cognitive load by triggering pattern recognition, enabling engineers to focus their brainpower on their tasks.</p><h3 id="consistency-predictability-and-familiarity" tabindex="-1">Consistency, Predictability and Familiarity <a class="header-anchor" href="#consistency-predictability-and-familiarity" aria-label="Permalink to &quot;Consistency, Predictability and Familiarity&quot;">​</a></h3><p>Consistency and Predictability are key to reducing cognitive load and facilitating the onboarding process.</p><p>More often than not, &quot;familiarity&quot; is what people call &quot;Good Developer Experience&quot;, and we believe that is good thing, imagine if JavaScript Programming Language Runtimes move around modules and global objects, change the syntax of the language, or change the meaning and behavior of built-in functions based on personal preferences, that would be a nightmare. We wouldn&#39;t be productive if we had to pay attention to every single detail every time we write code.</p><p>We also believe that &quot;Familiarity&quot; does not mean &quot;Perfection&quot;, and there is a cost to learning and adapting to a new convention,</p><p>But we believe that the cost is worth it in the long run. Although, the ADR may feel overwhelming at first, we promise that it will become second nature after a while, and some of the rules will lead you to a codebase that barely changes over time. They are that many ways to configure i18n</p><h3 id="strong-cohesion-controlled-coupling-and-risk-mitigation" tabindex="-1">Strong Cohesion, Controlled Coupling, and Risk Mitigation <a class="header-anchor" href="#strong-cohesion-controlled-coupling-and-risk-mitigation" aria-label="Permalink to &quot;Strong Cohesion, Controlled Coupling, and Risk Mitigation&quot;">​</a></h3><p>When something goes wrong, we need to add, remove, update or fix a use case; we need to answer the simple question:</p><ul><li>Where do we need to do that?</li></ul><p>The simplest way to answer that question is to ask which <a href="#route">Route</a> is involved, and work your way up or down the Application Tree.</p><p>For that reason, we need to have a strong cohesion and controlled coupling of the files between the routes is critical. The higher your changes are in the Application Tree, the more risk you are introducing to the application. The lower your changes are in the Application Tree, the less risk you are introducing to the application since the changes are more isolated.</p><p>Probably the most important part of the ADR is the fact that you can not import or have circular dependencies between sibling routes, you will require to move the files to a common root directory that is a parent to the routes. Signaling that the files are shared between the routes and that the files are increasing the risk of the application.</p><h3 id="server-vs-client" tabindex="-1">Server vs. Client <a class="header-anchor" href="#server-vs-client" aria-label="Permalink to &quot;Server vs. Client&quot;">​</a></h3><p>We should treat the server-side as the default rendering strategy, we opt-in to the client-side when we need to. Therefore, we discourage the naming convention around <code>*.server</code>. That means that we should create <code>*.client</code> files.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST</strong> not import between routes. You <strong>MUST</strong> use colocate the files to a common root directory that is a parent to the routes.</li><li>You <strong>MUST</strong> not have circular dependency between sibling directories. You <strong>MUST</strong> use a common root directory that is a parent to the sibling directories.</li><li>You <strong>MUST</strong> use <code>&lt;rootDir&gt;/src/@types</code> to store TypeScript definition files (<code>*.d.ts</code>).</li><li>You <strong>MUST</strong> use <code>&lt;rootDir&gt;/src/polyfills</code> to store polyfills.</li><li>You <strong>MUST</strong> use <code>_</code> as a prefix for <a href="#private-directory">Private Directories</a> under <code>&lt;rootDir&gt;/src/app</code> to opt-out of the routing system.</li><li>You <strong>SHOULD</strong> avoid re-exporting files, and you <strong>SHOULD</strong> use the file directly.</li><li>You <strong>SHOULD</strong> use relative imports when importing sibling files or nested to under the same parent directory.</li><li>You <strong>SHOULD</strong> use absolute imports when importing from a different parent directory.</li><li>You <strong>MUST NOT</strong> use <a href="#private-directory">Private Directories</a> inside <code>&lt;rootDir&gt;/src/libs/[lib name]</code>.</li><li>You <strong>MUST</strong> use <code>__tests__</code> for testing support files under <code>&lt;rootDir&gt;/src</code>.</li><li>You <strong>MUST</strong> colocate Component&#39;s Unit Test sibling to component file by using <code>[component name].test.[extension]</code>.</li><li>You <strong>MUST</strong> use <code>*.client.[extension]</code> to store client-side files.</li><li>You <strong>MUST NOT</strong> use <code>*.server.[extension]</code> suffix.</li></ul><h3 id="libraries-only" tabindex="-1">Libraries Only <a class="header-anchor" href="#libraries-only" aria-label="Permalink to &quot;Libraries Only&quot;">​</a></h3><ul><li>You <strong>MUST</strong> use <code>&lt;rootDir&gt;/src/libs/[lib name]</code> to store <a href="#libraries">Libraries</a>.</li><li>You <strong>SHOULD</strong> wait until you have at least two consumers with the exact same code in production for at least two months, that required the same changes to be made in all two consumers before adding anything to a <code>&lt;rootDir&gt;/src/libs/[lib name]</code>.</li><li>You <strong>SHOULD</strong> wait until you have at least three consumers with the exact same code in production for at least three months, that required the same changes to be made in all two consumers before moving a <code>&lt;rootDir&gt;/src/libs/[lib name]</code> to a separate package.</li><li>You <strong>MUST</strong> not have circular dependencies between <a href="#libraries">Libraries</a>.</li></ul><h3 id="next-js-only" tabindex="-1">Next.js Only <a class="header-anchor" href="#next-js-only" aria-label="Permalink to &quot;Next.js Only&quot;">​</a></h3><ul><li>You <strong>MUST</strong> use Next.js App Router directory structure.</li><li>You <strong>MUST NOT</strong> use Next.js Pages Router directory structure.</li><li>You <strong>MUST</strong> use <code>&lt;rootDir&gt;/src/app</code> directory to store the Next.js Router.</li><li>You <strong>MUST</strong> use <code>&lt;rootDir&gt;/public</code> to store static files.</li><li>You <strong>MUST NOT</strong> import Server Action files from another Server Action file.</li><li>You <strong>MUST NOT</strong> call a Server Action function from another Server Action function.</li><li>You <strong>MUST</strong> use <code>*Client</code> suffix for Component&#39;s name to indicate that the component is a client-side component when the name overlaps with the server-side component.</li><li>You <strong>MUST</strong> use <code>[locale]</code> path parameter for app-specific internationalization and localization.</li></ul><h3 id="react-native-only" tabindex="-1">React Native Only <a class="header-anchor" href="#react-native-only" aria-label="Permalink to &quot;React Native Only&quot;">​</a></h3><ul><li>You <strong>MUST</strong> use Expo Router directory structure.</li><li>You <strong>MUST</strong> use <code>&lt;rootDir&gt;/src/app</code> directory to store the Expo Router.</li><li>You <strong>MUST</strong> use <code>&lt;rootDir&gt;/src/assets</code> to store assets files.</li><li>You <strong>MUST NOT</strong> use <code>&lt;rootDir&gt;/assets</code> to store assets files.</li></ul><h3 id="vite-only" tabindex="-1">Vite Only <a class="header-anchor" href="#vite-only" aria-label="Permalink to &quot;Vite Only&quot;">​</a></h3><p>Related to Vite projects only.</p><ul><li>You <strong>MUST</strong> use <code>&lt;rootDir&gt;/src/app/index.tsx</code> as the entry point for the Vite application.</li></ul><h3 id="fractal-pattern" tabindex="-1">Fractal Pattern <a class="header-anchor" href="#fractal-pattern" aria-label="Permalink to &quot;Fractal Pattern&quot;">​</a></h3><p>A fractal pattern is a pattern that you could repeat over and over again.</p><ul><li><p>You <strong>MUST</strong> follow the fractal pattern under the <code>&lt;rootDir&gt;/src</code>, <code>&lt;rootDir&gt;/src/app</code>, <code>&lt;rootDir&gt;/src/components/[component name]</code>, and <code>&lt;rootDir&gt;/src/libs/[lib name]</code> directories.</p></li><li><p>You <strong>MUST</strong> prefix all directories under <code>&lt;rootDir&gt;/src/app</code> with <code>_</code> to opt-out of the routing system and define the directory as a <a href="#private-directory">Private Directory</a>.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/services</code> to store anything related to any communication with <a href="#external-services">External Services</a>.</p></li><li><p>You <strong>MUST</strong> use external service brand name as a file or subdirectory in <code>&lt;fractalDir&gt;/services/[service name]</code>.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/storages</code> to store anything related to the device. You <strong>MUST</strong> use <code>local</code>, <code>session</code>, <code>cookies</code>, <code>websql</code>, and <code>indexeddb</code> as subdirectories based on the storage type.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/schemas</code> to store anything related to Joi, Yup schemas or any similar package.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/components</code> to store reusable React components.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/hooks</code> to store reusable React hooks.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/contexts</code> to store React contexts definitions.</p></li><li></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/constants</code> to store constants variables.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/types</code> to store reusable TypeScript types.</p></li><li></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/styles</code> to store components styles such as CSS or Stylesheets.</p></li><li><p>You <strong>MUST</strong> colocate CSS Module Component&#39;s Styles sibling to component file with the following naming convention <code>[component name].module.[extension]</code>.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/assets</code> to store files such as images, fonts, and any other files that are no Stylesheets or JavaScript files.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/i18n</code> to store anything related to Internationalization.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/i18n/messages</code> to store the i18n messages.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/i18n/datetime</code> to store i18n date and time formatting. Read more about the intent at <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/DateTimeFormat" target="_blank" rel="noreferrer">Intl.DateTimeFormat</a>.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/i18n/list</code> to store i18n sensitive list formatting. Read more about the intent at <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/ListFormat" target="_blank" rel="noreferrer">Intl.ListFormat</a>.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/i18n/numbers</code> to store i18n number formatting. Read more about the intent at <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/NumberFormat" target="_blank" rel="noreferrer">Intl.NumberFormat</a>.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/i18n/plural</code> to store i18n pluralization formatting. Read more about the intent at <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/PluralRules" target="_blank" rel="noreferrer">Intl.PluralRules</a>.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/i18n/relative-time</code> to store i18n relative-time formatting. Read more about the intent at <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/RelativeTimeFormat" target="_blank" rel="noreferrer">Intl.RelativeTimeFormat</a>.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/helpers/datetime</code> to store anything related to Dates or Times. Except formatters, use <code>&lt;fractalDir&gt;/i18n/datetime</code> instead.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/helpers/currency</code> to store anything related to currency. Except formatters, use <code>&lt;fractalDir&gt;/i18n/numbers</code> instead.</p></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/helpers</code> to store anything that does not fall into any of the other helper directory categories.</p></li></ul><h4 id="next-js-fractal-pattern" tabindex="-1">Next.js Fractal Pattern <a class="header-anchor" href="#next-js-fractal-pattern" aria-label="Permalink to &quot;Next.js Fractal Pattern&quot;">​</a></h4><p>Related to Next.js projects only.</p><ul><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/server</code> to store anything related to the Next.js server-side code.</p></li><li><p>You <strong>MUST</strong> add <code>&#39;use server;&#39;</code> directive and <code>import &#39;server-only&#39;;</code> to the top of the files under <code>&lt;fractalDir&gt;/server</code>. Example:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;use server&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;server-only&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p>You <strong>MUST</strong> use <code>&lt;fractalDir&gt;/server/actions</code> to store anything related to Next.js Server Actions.</p></li></ul><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h2><h3 id="libraries" tabindex="-1">Libraries <a class="header-anchor" href="#libraries" aria-label="Permalink to &quot;Libraries&quot;">​</a></h3><p>Libraries are a set of shared code <code>intended to be moved to a separate package in the future.</code></p><h3 id="route" tabindex="-1">Route <a class="header-anchor" href="#route" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p>A Route, in the context of React DOM, Route is a path or segments of URL that the user is visiting.</p><p>A Route, in the context of React Native, it is a screen.</p><h3 id="external-services" tabindex="-1">External services <a class="header-anchor" href="#external-services" aria-label="Permalink to &quot;External services&quot;">​</a></h3><p>Any piece of software external to your application that crosses some network boundary such as APIs, 3rd party tools (Google Analytics, Sentry), and so on.</p><h3 id="private-directory" tabindex="-1">Private Directory <a class="header-anchor" href="#private-directory" aria-label="Permalink to &quot;Private Directory&quot;">​</a></h3><p>A Private Directory is a directory that should not be considered by the routing system, thereby opting the directories and all its subdirectories out of routing system. This is inspired by the Next.js App Router directory structure.</p>`,44)])])}const g=t(a,[["render",n]]);export{p as __pageData,g as default};
